//! Host-owned public station directory and explicitly selected live streams.
use crate::Result;use serde_json::Value;
pub(crate) fn station(v:&Value)->bool{v.as_str().is_some_and(|s|uuid::Uuid::parse_str(s).is_ok_and(|id|id.to_string()==s))}
pub(crate) fn request(service:&str,args:&Value)->Result<()>{let a=args.as_object().ok_or("Radio arguments must be an object")?;match service{
"radio.search"=>{if a.keys().any(|k|!["query","tag","country","language","offset","refresh","retry_unavailable","auto_hide","show_unavailable","hide_station"].contains(&k.as_str())){return Err("Unsupported radio search argument".into())}for(k,max)in[("query",80),("tag",32),("country",2),("language",32)]{if let Some(v)=a.get(k){if v.as_str().is_none_or(|s|s.chars().count()>max||s.chars().any(char::is_control)){return Err("Invalid radio search filter".into())}}}if a.get("hide_station").is_some_and(|v|!station(v)){return Err("Choose a valid station to hide".into())}for key in ["auto_hide","show_unavailable"]{if a.get(key).is_some_and(|v|!v.is_boolean()){return Err("Use boolean radio visibility settings".into())}}if a.get("retry_unavailable").is_some_and(|v|!v.is_boolean()){return Err("Use a boolean unavailable-station reset flag".into())}if a.get("refresh").is_some_and(|v|!v.is_boolean()){return Err("Use a boolean radio refresh flag".into())}if a.get("offset").is_some_and(|v|v.as_u64().is_none_or(|n|n>1_000_000||n%20!=0)){return Err("Radio page must be a multiple of20 within the catalog limit".into())}},
"radio.play"=>{if a.len()!=1||!station(&args["station"]){return Err("Choose a station from the radio directory".into())}},_=>return Err("Unsupported radio service".into())};Ok(())}
pub(crate) fn reply(service:&str,v:&Value)->Result<()>{if v.to_string().len()>65536{return Err("Radio response exceeds its limit".into())}if service=="radio.play"{crate::sdk_tasks::reply("media.status",&v["player"])?;if !station(&v["station"]["id"]){return Err("Invalid playing station".into())}}else{let rows=v["items"].as_array().filter(|r|r.len()<=20).ok_or("Invalid radio page")?;for row in rows{if !station(&row["id"])||row["name"].as_str().is_none_or(|s|s.is_empty()||s.chars().count()>100||s.chars().any(char::is_control)){return Err("Invalid radio station".into())}}}Ok(())}
#[cfg(test)]mod tests{use super::*;use serde_json::json;
#[test]fn radio_requests_never_accept_urls_credentials_or_unbounded_pages(){request("radio.search",&json!({"tag":"jazz","offset":20})).unwrap();request("radio.search",&json!({"offset":1000000,"refresh":true})).unwrap();assert!(request("radio.search",&json!({"refresh":"yes"})).is_err());for v in[json!({"url":"https://evil.example.org"}),json!({"offset":1001}),json!({"query":"x".repeat(81)})]{assert!(request("radio.search",&v).is_err())}assert!(request("radio.play",&json!({"station":"https://evil.example.org"})).is_err());assert!(request("radio.play",&json!({"station":uuid::Uuid::new_v4().to_string(),"url":"https://evil.example.org"})).is_err());request("radio.play",&json!({"station":uuid::Uuid::new_v4().to_string()})).unwrap();}
#[test]fn radio_replies_reject_foreign_shaped_station_rows(){assert!(reply("radio.search",&json!({"items":[{"id":"oops","name":"Fake"}]})).is_err());assert!(reply("radio.search",&json!({"items":(0..21).map(|_|json!({"id":uuid::Uuid::new_v4().to_string(),"name":"Radio"})).collect::<Vec<_>>()})).is_err());}
}
